mapper.select:
/* SQL ID : isry.cysns.stats.hlcampsrvcprfmnc.mapper.HlCampSrvcPrfmncMapper selectHlCampSrvcPrfmncList - [응용3팀]이상훈 */
WITH TMP000 AS ( SELECT NVL(B.INDV_IDNTFC_NO,A.TRPR_INFO_NO) AS TRPR_INFO_NO , B.SXDC_SE_CD , A.LINK_TYPE_SE_CD , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , A.ADDTNG_TRL_INSP_ENFORC_YN FROM ACA200 A JOIN SEA200 B ON B.TRPR_INFO_NO = A.TRPR_INFO_NO AND B.DEL_YN = 'N' LEFT JOIN ACA210 C ON C.DGNSS_EXMN_MNG_NO = A.DGNSS_EXMN_MNG_NO LEFT JOIN ACA400 D ON D.DGNSS_EXMN_MNG_NO = A.DGNSS_EXMN_MNG_NO LEFT JOIN ( SELECT E2.RCPT_TRPR_INFO_NO , E1.RCPT_INST_NO , E1.RQST_YMD , ROW_NUMBER() OVER(PARTITION BY E2.SRVC_PVSN_RQST_NO ORDER BY E2.RCPT_SN DESC) AS ROW_NUMBER FROM SEB400 E1 JOIN SEB420 E2 ON E2.SRVC_PVSN_RQST_NO = E1.SRVC_PVSN_RQST_NO AND E2.DEL_YN = 'N' WHERE 1=1 AND E1.DEL_YN = 'N' AND E1.LINK_TYPE_SE_CD BETWEEN '07' AND '10' ) E ON E.RCPT_TRPR_INFO_NO = A.TRPR_INFO_NO AND E.ROW_NUMBER = 1 LEFT JOIN SAA000 F ON F.INST_NO = E.RCPT_INST_NO JOIN SEB100 G ON G.CASE_MNG_NO = A.CASE_MNG_NO AND G.CASE_MNG_ODRNO = A.CASE_MNG_ODRNO JOIN SEB150 G2 ON G2.CASE_MNG_NO = G.CASE_MNG_NO AND G2.CASE_MNG_ODRNO = G.CASE_MNG_ODRNO AND G2.PCHPRS_YN = 'Y' JOIN SAA000 G3 ON G3.INST_NO = G2.PIC_INST_NO WHERE 1=1 AND G.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
AND NVL(F.SGG_CD,G3.SGG_CD) = #{SGG_CD}
AND SUBSTR(NVL(F.SGG_CD,G3.SGG_CD),1,2) = #{CTPV_CD}
AND G3.INST_NO IN
#{item}
/*종사자*/ AND G2.CASE_PIC_NO = #{ENFSN_NO}
AND NVL(F.INST_NO,G3.INST_NO) = #{INST_NO}
AND A.MEDIAA_SCHL_SE_CD = #{ACBG}
AND NVL(C.GRADE_SE_CD,D.GRADE_SE_CD) = #{GRADE}
AND A.TRPR_CHAR_SE_CD = #{TRPR_SE}
AND ( A.BEFFAT_INTNET_DGNSS_SE_CD#{LEVEL} AND A.BEFFAT_SMRTP_DGNSS_SE_CD#{LEVEL} AND A.BEFFAT_GAMBLE_DGNSS_SE_CD#{LEVEL} )
AND ( A.BEFFAT_INTNET_DGNSS_SE_CD #{LEVEL} OR A.BEFFAT_SMRTP_DGNSS_SE_CD #{LEVEL} OR A.BEFFAT_GAMBLE_DGNSS_SE_CD #{LEVEL} )
A.BEFFAT_INTNET_DGNSS_SE_CD
A.BEFFAT_SMRTP_DGNSS_SE_CD
A.BEFFAT_GAMBLE_DGNSS_SE_CD
IS NOT NULL #{LEVEL}
A.BEFFAT_INTNET_DGNSS_SE_CD
A.BEFFAT_SMRTP_DGNSS_SE_CD
A.BEFFAT_GAMBLE_DGNSS_SE_CD
IS NOT NULL #{LEVEL}
)
SELECT NVL(CASE A.LINK_TYPE_SE_CD WHEN '07' THEN '학교 진단' WHEN '08' THEN '유관기관 진단' WHEN '09' THEN '센터 진단' WHEN '10' THEN '미연계(직접등록)' END,'합계') AS LINK_SE /* 연계구분 */ , NVL(SUM(B.HL_CAMP_REAL_NOPE_M),0) AS HL_CAMP_REAL_NOPE_M /* 치유캠프-실인원-남 */ , NVL(SUM(B.HL_CAMP_REAL_NOPE_F),0) AS HL_CAMP_REAL_NOPE_F /* 치유캠프-실인원-여 */ , NVL(SUM(B.HL_CAMP_REAL_NOPE_T),0) AS HL_CAMP_REAL_NOPE_T /* 치유캠프-실인원-계 */ , NVL(SUM(B.FAM_HL_CAMP_REAL_NOPE_M),0) AS FAM_HL_CAMP_REAL_NOPE_M /* 가족치유캠프-실인원-남 */ , NVL(SUM(B.FAM_HL_CAMP_REAL_NOPE_F),0) AS FAM_HL_CAMP_REAL_NOPE_F /* 가족치유캠프-실인원-여 */ , NVL(SUM(B.FAM_HL_CAMP_REAL_NOPE_T),0) AS FAM_HL_CAMP_REAL_NOPE_T /* 가족치유캠프-실인원-계*/ , NVL(SUM(B.INSTOP_NOPE_M),0) AS INSTOP_NOPE_M /* 인스탑-연인원-남 */ , NVL(SUM(B.INSTOP_NOPE_F),0) AS INSTOP_NOPE_F /* 인스탑-연인원-여 */ , NVL(SUM(B.INSTOP_NOPE_T),0) AS INSTOP_NOPE_T /* 인스탑-연인원-계 */ , NVL(SUM(B.INSTOP_REAL_NOPE_M),0) AS INSTOP_REAL_NOPE_M /* 인스탑-실인원-남 */ , NVL(SUM(B.INSTOP_REAL_NOPE_F),0) AS INSTOP_REAL_NOPE_F /* 인스탑-실인원-여 */ , NVL(SUM(B.INSTOP_REAL_NOPE_T),0) AS INSTOP_REAL_NOPE_T /* 인스탑-실인원-계 */ FROM ( SELECT '07' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '08' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '09' AS LINK_TYPE_SE_CD FROM DUAL UNION SELECT '10' AS LINK_TYPE_SE_CD FROM DUAL) A LEFT JOIN ( SELECT B1.LINK_TYPE_SE_CD AS LINK_TYPE_SE_CD /*연계구분코드*/ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE3 AND B1.SXDC_SE_CD = 'M' THEN B1.TRPR_INFO_NO END) AS HL_CAMP_REAL_NOPE_M /* 치유캠프-실인원-남 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE3 AND B1.SXDC_SE_CD = 'F' THEN B1.TRPR_INFO_NO END) AS HL_CAMP_REAL_NOPE_F /* 치유캠프-실인원-여 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE3 THEN B1.TRPR_INFO_NO END) AS HL_CAMP_REAL_NOPE_T /* 치유캠프-실인원-계 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE4 AND B1.SXDC_SE_CD = 'M' THEN B1.TRPR_INFO_NO END) AS FAM_HL_CAMP_REAL_NOPE_M /* 가족치유캠프-실인원-남 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE4 AND B1.SXDC_SE_CD = 'F' THEN B1.TRPR_INFO_NO END) AS FAM_HL_CAMP_REAL_NOPE_F /* 가족치유캠프-실인원-여 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE4 THEN B1.TRPR_INFO_NO END) AS FAM_HL_CAMP_REAL_NOPE_T /* 가족치유캠프-실인원-계*/ , COUNT(CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE5 AND B1.SXDC_SE_CD = 'M' THEN B1.TRPR_INFO_NO END) AS INSTOP_NOPE_M /* 인스탑-연인원-남 */ , COUNT(CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE5 AND B1.SXDC_SE_CD = 'F' THEN B1.TRPR_INFO_NO END) AS INSTOP_NOPE_F /* 인스탑-연인원-여 */ , COUNT(CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE5 THEN B1.TRPR_INFO_NO END) AS INSTOP_NOPE_T /* 인스탑-연인원-계 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE5 AND B1.SXDC_SE_CD = 'M' THEN B1.TRPR_INFO_NO END) AS INSTOP_REAL_NOPE_M /* 인스탑-실인원-남 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE5 AND B1.SXDC_SE_CD = 'F' THEN B1.TRPR_INFO_NO END) AS INSTOP_REAL_NOPE_F /* 인스탑-실인원-여 */ , COUNT(DISTINCT CASE WHEN B3.EXCN_SRVC_DETAIA_BIZ_NO = B2.ADDTNG_MNG_VALUE5 THEN B1.TRPR_INFO_NO END) AS INSTOP_REAL_NOPE_T /* 인스탑-실인원-계 */ FROM TMP000 B1 JOIN SAC100 B2 ON B2.CMMNS_CD_ID = 'INTNET_SMRTP_STATS_SE_CD' AND B2.CMMNS_CD_VALUE = '01' JOIN SEB540 B3 ON B3.CASE_MNG_NO = B1.CASE_MNG_NO AND B3.CASE_MNG_ODRNO = B1.CASE_MNG_ODRNO AND B3.EXCN_SRVC_DETAIA_BIZ_NO IN (B2.ADDTNG_MNG_VALUE3,B2.ADDTNG_MNG_VALUE4,B2.ADDTNG_MNG_VALUE5) AND B3.DEL_YN = 'N' GROUP BY B1.LINK_TYPE_SE_CD ) B ON B.LINK_TYPE_SE_CD = A.LINK_TYPE_SE_CD GROUP BY ROLLUP(A.LINK_TYPE_SE_CD) ORDER BY A.LINK_TYPE_SE_CD
